Here is the commit message:
wifi: mt76: mt7996: Fix possible oob access in
 mt7996_mac_write_txwi_80211()

Check frame length before accessing the mgmt fields in
mt7996_mac_write_txwi_80211 in order to avoid a possible oob access.

Fixes: 98686cd21624c ("wifi: mt76: mt7996: add driver for MediaTek Wi-Fi 7 (802.11be) devices")
Signed-off-by: Lorenzo Bianconi <lorenzo@kernel.org>
Link: https://patch.msgid.link/20260226-mt76-addba-req-oob-access-v1-1-b0f6d1ad4850@kernel.org
Signed-off-by: Johannes Berg <johannes.berg@intel.com>

Here is the root cause:
The function mt7996_mac_write_txwi_80211() accesses mgmt frame fields (category and action code) without verifying that the skb length is sufficient to contain those fields, leading to a potential out-of-bounds read when processing short or malformed frames.

Here is the patch:

 static void
 mt7996_mac_write_txwi_80211(struct mt7996_dev *dev, __le32 *txwi,
 			    struct sk_buff *skb,
 			    struct ieee80211_key_conf *key,
 			    struct mt76_wcid *wcid)
 {
 	struct ieee80211_hdr *hdr = (struct ieee80211_hdr *)skb->data;
 	struct ieee80211_mgmt *mgmt = (struct ieee80211_mgmt *)skb->data;
 	struct ieee80211_tx_info *info = IEEE80211_SKB_CB(skb);
 	bool multicast = is_multicast_ether_addr(hdr->addr1);
 	u8 tid = skb->priority & IEEE80211_QOS_CTL_TID_MASK;
 	__le16 fc = hdr->frame_control, sc = hdr->seq_ctrl;
 	u16 seqno = le16_to_cpu(sc);
 	bool hw_bigtk = false;
 	u8 fc_type, fc_stype;
 	u32 val;

 	if (ieee80211_is_action(fc) &&
+	    skb->len >= IEEE80211_MIN_ACTION_SIZE + 1 &&
 	    mgmt->u.action.category == WLAN_CATEGORY_BACK &&
 	    mgmt->u.action.u.addba_req.action_code == WLAN_ACTION_ADDBA_REQ) {
 		if (is_mt7990(&dev->mt76))
 			txwi[6] |= cpu_to_le32(FIELD_PREP(MT_TXD6_TID_ADDBA, tid));
 		else
 			txwi[7] |= cpu_to_le32(MT_TXD7_MAC_TXD);

 		tid = MT_TX_ADDBA;
 	} else if (ieee80211_is_mgmt(hdr->frame_control)) {
 		tid = MT_TX_NORMAL;
 	}

 	val = FIELD_PREP(MT_TXD1_HDR_FORMAT, MT_HDR_FORMAT_802_11) |
 	      FIELD_PREP(MT_TXD1_HDR_INFO,
 			 ieee80211_get_hdrlen_from_skb(skb) / 2) |
 	      FIELD_PREP(MT_TXD1_TID, tid);

 	if (!ieee80211_is_data(fc) || multicast ||
 	    info->flags & IEEE80211_TX_CTL_USE_MINRATE)
 		val |= MT_TXD1_FIXED_RATE;

 	if (is_mt7990(&dev->mt76) && ieee80211_is_beacon(fc) &&
 	    (wcid->hw_key_idx2 == 6 || wcid->hw_key_idx2 == 7))
 		hw_bigtk = true;

 	if ((key && multicast && ieee80211_is_robust_mgmt_frame(skb)) || hw_bigtk) {
 		val |= MT_TXD1_BIP;
 		txwi[3] &= ~cpu_to_le32(MT_TXD3_PROTECT_FRAME);
 	}

 	txwi[1] |= cpu_to_le32(val);

 	fc_type = (le16_to_cpu(fc) & IEEE80211_FCTL_FTYPE) >> 2;
 	fc_stype = (le16_to_cpu(fc) & IEEE80211_FCTL_STYPE) >> 4;

 	val = FIELD_PREP(MT_TXD2_FRAME_TYPE, fc_type) |
 	      FIELD_PREP(MT_TXD2_SUB_TYPE, fc_stype);

 	if (ieee80211_has_morefrags(fc) && ieee80211_is_first_frag(sc))
 		val |= FIELD_PREP(MT_TXD2_FRAG, MT_TX_FRAG_FIRST);
 	else if (ieee80211_has_morefrags(fc) && !ieee80211_is_first_frag(sc))
 		val |= FIELD_PREP(MT_TXD2_FRAG, MT_TX_FRAG_MID);
 	else if (!ieee80211_has_morefrags(fc) && !ieee80211_is_first_frag(sc))
 		val |= FIELD_PREP(MT_TXD2_FRAG, MT_TX_FRAG_LAST);
 	else
 		val |= FIELD_PREP(MT_TXD2_FRAG, MT_TX_FRAG_NONE);

 	txwi[2] |= cpu_to_le32(val);

 	txwi[3] |= cpu_to_le32(FIELD_PREP(MT_TXD3_BCM, multicast));
 	if (ieee80211_is_beacon(fc)) {
 		txwi[3] &= ~cpu_to_le32(MT_TXD3_SW_POWER_MGMT);
 		txwi[3] |= cpu_to_le32(MT_TXD3_REM_TX_COUNT);
 	}

 	if (multicast && ieee80211_vif_is_mld(info->control.vif)) {
 		val = MT_TXD3_SN_VALID |
 		      FIELD_PREP(MT_TXD3_SEQ, IEEE80211_SEQ_TO_SN(seqno));
 		txwi[3] |= cpu_to_le32(val);
 	}

 	if (info->flags & IEEE80211_TX_CTL_INJECTED) {
 		if (ieee80211_is_back_req(hdr->frame_control)) {
 			struct ieee80211_bar *bar;

 			bar = (struct ieee80211_bar *)skb->data;
 			seqno = le16_to_cpu(bar->start_seq_num);
 		}

 		val = MT_TXD3_SN_VALID |
 		      FIELD_PREP(MT_TXD3_SEQ, IEEE80211_SEQ_TO_SN(seqno));
 		txwi[3] |= cpu_to_le32(val);
 		txwi[3] &= ~cpu_to_le32(MT_TXD3_HW_AMSDU);
 	}

 	if (ieee80211_vif_is_mld(info->control.vif) &&
 	    (multicast || unlikely(skb->protocol == cpu_to_be16(ETH_P_PAE))))
 		txwi[5] |= cpu_to_le32(MT_TXD5_FL);

 	if (ieee80211_is_nullfunc(fc) && ieee80211_has_a4(fc) &&
 	    ieee80211_vif_is_mld(info->control.vif)) {
 		txwi[5] |= cpu_to_le32(MT_TXD5_FL);
 		txwi[6] |= cpu_to_le32(MT_TXD6_DIS_MAT);
 	}

 	if (!wcid->sta && ieee80211_is_mgmt(fc))
 		txwi[6] |= cpu_to_le32(MT_TXD6_DIS_MAT);
 }



